namespace LegacyAVR.UI.ViewModels;

/// <summary>One searchable entry of the Settings Guide tab.</summary>
/// <param name="Control">v1.2.0: key of the live control shown inline (MainWindow resource "HelpCtl.&lt;key&gt;"); "" = none.</param>
public sealed record HelpEntry(
    string Category,
    string Title,
    string WhatItDoes,
    string Tradeoffs,
    string StartingPoint,
    string Keywords = "",
    string Control = "")
{
    public bool HasControl => Control.Length > 0;
}

